package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.UserService; import com.agencytrip.agencytripapi.domain.model.User; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@Tag(name="Registro") @RestController @RequestMapping("/api/Registro") public class RegistrationController {private final UserService service;public RegistrationController(UserService s){service=s;}@Operation(summary="Registrar un cliente",description="Crea una cuenta activa con rol CLIENTE y contraseña protegida con BCrypt.") @PostMapping public Map<String,Object> register(@Valid @RequestBody Requests.Register r){User u=service.register(r);return Map.of("mensaje","Usuario registrado correctamente.","usuario",ApiResponses.userAuth(u,"CLIENTE"));}}
